// Chuẩn hóa dữ liệu theo cấu trúc HĐĐT Thông tư 78 / Nghị định 123
const payload = $json.body || $json;
const customer = payload.customer || {};
const items = payload.items || [];
const totalAmount = payload.totalAmount || 0;
const taxRate = payload.taxRate || 8; // Thuế suất 8% cho ẩm thực theo quy định

const vatAmount = Math.round(totalAmount * taxRate / (100 + taxRate));
const preTaxAmount = totalAmount - vatAmount;

const invoicePayload = {
  invoiceSeries: "1C26TDP", // Ký hiệu hóa đơn Đất Phú 2026
  buyerName: customer.name || "Khách hàng lẻ không lấy hóa đơn",
  buyerTaxCode: customer.taxCode || "",
  buyerAddress: customer.address || "Tuy Hòa, Phú Yên",
  buyerEmail: customer.email || "",
  buyerPhone: customer.phone || "",
  totalAmount: totalAmount,
  preTaxAmount: preTaxAmount,
  vatAmount: vatAmount,
  taxRate: taxRate,
  issueDate: new Date().toISOString(),
  items: items.map((it, idx) => ({
    lineNumber: idx + 1,
    itemName: it.name,
    unit: it.unit || "Đĩa/Tô",
    quantity: it.qty || 1,
    unitPrice: it.price || 0,
    amount: (it.price || 0) * (it.qty || 1)
  }))
};

return [{ json: invoicePayload }];
